class Solution {
public:
    std::vector<int> getSubarrayBeauty(std::vector<int>& nums, int k, int x) {
        std::vector<int> count(101, 0);
        std::vector<int> ans;
        for (int i = 0; i < (int)nums.size(); i++) {
            count[nums[i] + 50]++;
            if (i >= k) {
                count[nums[i - k] + 50]--;
            }
            if (i >= k - 1) {
                int seen = 0;
                int beauty = 0;
                for (int v = -50; v < 0; v++) {
                    seen += count[v + 50];
                    if (seen >= x) {
                        beauty = v;
                        break;
                    }
                }
                ans.push_back(beauty);
            }
        }
        return ans;
    }
};

class Solution {
    public int[] getSubarrayBeauty(int[] nums, int k, int x) {
        int[] count = new int[101];
        int[] ans = new int[nums.length - k + 1];
        int idx = 0;
        for (int i = 0; i < nums.length; i++) {
            count[nums[i] + 50]++;
            if (i >= k) {
                count[nums[i - k] + 50]--;
            }
            if (i >= k - 1) {
                int seen = 0;
                int beauty = 0;
                for (int v = -50; v < 0; v++) {
                    seen += count[v + 50];
                    if (seen >= x) {
                        beauty = v;
                        break;
                    }
                }
                ans[idx++] = beauty;
            }
        }
        return ans;
    }
}

